// Hindcast load-test plan: api 0.35 cores
// Drives api to 77% of its modelled capacity: 56.9 req/s on 1 replica of 73.8 req/s.
// 5 steps from the history's peak (35.8 req/s at the entry) to 56.9 req/s, each held 120 s (13 min in all).
// It stops itself (abortOnFail) as soon as a step's errors pass 1% or its p99 passes 500 ms: the SLO.
//
//   BASE_URL=https://staging.example.com k6 run api-0-35-cores.k6.js
// AUTH_HEADER, when set, is sent as the Authorization header. No credential is written in this file.
// Generated by hindcast plan_load_test from the model "my system". Fill in INPUTS; change the rates with plan_load_test.
import http from 'k6/http';
import exec from 'k6/execution';

const BASE_URL = __ENV.BASE_URL;
const AUTH = __ENV.AUTH_HEADER;

// ---- INPUTS: setup() refuses to start while one is missing
// values for each {placeholder} in the paths below, one picked at random per request
const PARAMS = {
};
// the JSON body of each endpoint that sends one; '' sends none
const BODIES = {
};
// paths to request for the traffic the history names no routes for (it had no traces): one picked at random per request
const ROUTES = {
  "web (all requests)": [],
};

// ---- the plan: the recorded endpoint mix, and the entry rate of each step
const ENDPOINTS = {
  e0: { id: "web (all requests)", method: "GET", path: "", body: false, routes: true },
};
// when each step runs (seconds from the start, its ramp included) and the entry rate it holds
const STEPS = [
  { step: 1, from: 0, to: 180, rps: 35.8 },
  { step: 2, from: 180, to: 330, rps: 41.1 },
  { step: 3, from: 330, to: 480, rps: 46.3 },
  { step: 4, from: 480, to: 630, rps: 51.6 },
  { step: 5, from: 630, to: 780, rps: 56.9 },
];

export const options = {
  discardResponseBodies: true,
  scenarios: {
    // web (all requests): 100% of the mix
    e0: { executor: 'ramping-arrival-rate', exec: 'hit', startRate: 0, timeUnit: '1m', preAllocatedVUs: 29, maxVUs: 145, stages: [{ duration: '60s', target: 2147 }, { duration: '120s', target: 2147 }, { duration: '30s', target: 2463 }, { duration: '120s', target: 2463 }, { duration: '30s', target: 2779 }, { duration: '120s', target: 2779 }, { duration: '30s', target: 3095 }, { duration: '120s', target: 3095 }, { duration: '30s', target: 3412 }, { duration: '120s', target: 3412 }] },
  },
  // per step, so a step that hurts stops the test at that step; 30 s of grace at the start
  thresholds: {
    'http_req_failed{step:1}': [{ threshold: 'rate<=0.01', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_duration{step:1}': [{ threshold: 'p(99)<=500', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_failed{step:2}': [{ threshold: 'rate<=0.01', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_duration{step:2}': [{ threshold: 'p(99)<=500', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_failed{step:3}': [{ threshold: 'rate<=0.01', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_duration{step:3}': [{ threshold: 'p(99)<=500', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_failed{step:4}': [{ threshold: 'rate<=0.01', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_duration{step:4}': [{ threshold: 'p(99)<=500', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_failed{step:5}': [{ threshold: 'rate<=0.01', abortOnFail: true, delayAbortEval: '30s' }],
    'http_req_duration{step:5}': [{ threshold: 'p(99)<=500', abortOnFail: true, delayAbortEval: '30s' }],
  },
  summaryTrendStats: ['avg', 'p(50)', 'p(90)', 'p(99)', 'max'],
};

export function setup() {
  if (!BASE_URL) throw new Error('set BASE_URL to the system under test, e.g. BASE_URL=https://staging.example.com');
  const missing = [];
  for (const e of Object.values(ENDPOINTS)) {
    const re = /\{([^}]+)\}/g;
    let m;
    while ((m = re.exec(e.path))) if (!(PARAMS[m[1]] || []).length) missing.push(`PARAMS["${m[1]}"] (${e.id})`);
    if (e.body && BODIES[e.id] == null) missing.push(`BODIES["${e.id}"]`);
    if (e.routes && !(ROUTES[e.id] || []).length) missing.push(`ROUTES["${e.id}"]`);
  }
  if (missing.length) throw new Error(`fill in before running: ${[...new Set(missing)].join(', ')}`);
  return { t0: Date.now() };
}

function stepAt(s) {
  for (const x of STEPS) if (s < x.to) return x.step;
  return STEPS[STEPS.length - 1].step;
}

export function hit(data) {
  const e = ENDPOINTS[exec.scenario.name];
  const pick = (a) => a[Math.floor(Math.random() * a.length)];
  const path = e.routes ? pick(ROUTES[e.id]) : e.path.replace(/\{([^}]+)\}/g, (_, k) => encodeURIComponent(pick(PARAMS[k])));
  const headers = {};
  if (AUTH) headers.Authorization = AUTH;
  const body = e.body ? BODIES[e.id] : null;
  if (body) headers['Content-Type'] = 'application/json';
  http.request(e.method, BASE_URL + path, body || null, { headers, timeout: '5000ms', tags: { step: String(stepAt((Date.now() - data.t0) / 1000)), endpoint: e.id } });
}

